import{_ as a,o as L,c as t,a2 as l}from"./chunks/framework.Bg-Zxr5O.js";const c=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"manual-zh/VALUE-LABELS.md","filePath":"manual-zh/VALUE-LABELS.md","lastUpdated":1785684581000}'),o={name:"manual-zh/VALUE-LABELS.md"};function A(r,e,p,E,n,d){return L(),t("div",null,[...e[0]||(e[0]=[l(`<h3 id="_11-11-value-labels" tabindex="-1">11.11 VALUE LABELS <a class="header-anchor" href="#_11-11-value-labels" aria-label="Permalink to &quot;11.11 VALUE LABELS&quot;">​</a></h3><p>变量的值可以与任意文本字符串相关联。这样，一个短值可以代表一个更长、更具描述性的标签。</p><p>数值变量和字符串变量都可以给定标签。对于字符串变量，值区分大小写，因此例如，如果一个大写值及其小写变体都出现在数据中，则必须分别对其加标签。</p><pre><code>VALUE LABELS
        /var_list value ’label’ [value ’label’]…
</code></pre><p><code>VALUE LABELS</code> 允许将变量的值与标签相关联。</p><p>要为一个或多个变量设置值标签，请在斜杠（‘/’）后指定变量名，后跟以空格分隔的值及其关联标签列表。</p><p>输出中的值标签通常会自动换行。在标签字符串中放入 ‘\\n’ 可在该处强制换行。标签仍可能在其他位置被换行。</p><p>在执行 <code>VALUE LABELS</code> 之前，会清除所指定变量上任何已有的值标签。使用 <code>ADD VALUE LABELS</code>（见 <a href="./ADD-VALUE-LABELS">ADD VALUE LABELS</a>）可以在不清空已有标签的情况下添加值标签。</p>`,8)])])}const s=a(o,[["render",A]]);export{c as __pageData,s as default};
